import { useCallback, useState } from 'react';
import { Button, Card, SegmentedRadioGroup, Text, useLang } from '@gravity-ui/uikit';

import { appI18n, setAppLang } from './i18n';

export function App() {
  const { lang } = useLang();
  const { t } = appI18n.useTranslation();
  const [count, setCount] = useState(0);

